package in.asmj.ride.model;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;import java.util.ArrayList;import java.util.List;
@Document("users") public class UserAccount {
 @Id private String id;private String name,email,mobile,passwordHash,role,status="PENDING",otpHash;private boolean mobileVerified, available; private String fleetOwnerId;private UploadedAsset profilePhoto;private List<UploadedAsset> documents=new ArrayList<>();private Instant otpExpiry,createdAt=Instant.now();
 public String getId(){return id;}public String getName(){return name;}public void setName(String x){name=x;}public String getEmail(){return email;}public void setEmail(String x){email=x;}public String getMobile(){return mobile;}public void setMobile(String x){mobile=x;}public String getPasswordHash(){return passwordHash;}public void setPasswordHash(String x){passwordHash=x;}public String getRole(){return role;}public void setRole(String x){role=x;}public String getStatus(){return status;}public void setStatus(String x){status=x;}public boolean isAvailable(){return available;}public void setAvailable(boolean x){available=x;}public String getFleetOwnerId(){return fleetOwnerId;}public void setFleetOwnerId(String x){fleetOwnerId=x;}public boolean isMobileVerified(){return mobileVerified;}public void setMobileVerified(boolean x){mobileVerified=x;}public String getOtpHash(){return otpHash;}public void setOtpHash(String x){otpHash=x;}public Instant getOtpExpiry(){return otpExpiry;}public void setOtpExpiry(Instant x){otpExpiry=x;}public UploadedAsset getProfilePhoto(){return profilePhoto;}public void setProfilePhoto(UploadedAsset x){profilePhoto=x;}public List<UploadedAsset> getDocuments(){return documents;}public void setDocuments(List<UploadedAsset> x){documents=x==null?new ArrayList<>():x;}
}